sp_widget.script:
(function() {
  /* I49: staff embed - journey timeline + score visual. Fed by Lumen's
     table/record params; table is WHITELISTED to the Hub request table. */
  var TABLE = 'x_snc_ptag_engage_engagement_request';
  data.denied = false;
  data.ready = false;
  try {
    if (!new x_snc_ptag_engage.PTAGHubAccess().isStaff()) { data.denied = true; return; }
  } catch (e) { data.denied = true; return; }
  var tbl = String($sp.getParameter('table') || '');
  var rid = String($sp.getParameter('record') || '');
  if (tbl !== TABLE || !/^[0-9a-f]{32}$/.test(rid)) { return; }
  var gr = new GlideRecord(TABLE);
  if (!gr.get(rid)) { return; }
  data.ready = true;
  data.number = gr.getValue('number');
  data.short_description = String(gr.getValue('short_description') || '');
  var state = String(gr.getValue('state') || '');
  data.entered = gr.state_entered_on.getDisplayValue();

  var HAPPY = ['1', '-1', '2', '4', '5', '3'];
  var LABELS = {'1':'Submitted','-1':'Under Review','2':'In Backlog','4':'Planned',
                '5':'In Development','3':'Completed','-2':'Need More Info',
                '7':'Unlikely to Implement','9':'Cancelled','8':'Duplicate'};
  var idx = HAPPY.indexOf(state);
  data.journey = [];
  for (var i = 0; i < HAPPY.length; i++) {
    data.journey.push({label: LABELS[HAPPY[i]],
                       done: idx > -1 && i < idx,
                       current: i === idx});
  }
  var NEG = {'9': 1, '8': 1};
  data.branch = (idx === -1 && state)
    ? {label: LABELS[state] || ('State ' + state), neg: !!NEG[state]}
    : null;

  data.score = parseInt(gr.getValue('score'), 10);
  data.score = isNaN(data.score) ? null : data.score;
  data.band = gr.score_band.getDisplayValue() || '';
  data.locked = gr.getValue('score_locked') === '1' || gr.getValue('score_locked') === 'true';
  var SIGNALS = [['pipeline','Pipeline'],['business_owner','Business Owner'],
                 ['executive_sponsor','Exec Sponsor'],['corporate_alignment','Corp Alignment'],
                 ['budget','Budget'],['has_customers','Existing Customers'],
                 ['certified_resources','Certified Resources']];
  data.signals = [];
  for (var s = 0; s < SIGNALS.length; s++) {
    var v = gr.getValue(SIGNALS[s][0]);
    data.signals.push({label: SIGNALS[s][1], on: v === '1' || v === 'true'});
  }
})();
